data.responseTransform:
{
"SUCCESS":false,
"MESSAGE":$coalesce([$state.lastError.message, "Unexpected error occurred, please review data flow logs for further details."])
}

data.transform:
(
	$id := $cuid();
	$returnWO := $state.context.LOCAL.returnWorkOrder;
	$request := $state.context.REQUEST.DATA;
	$returnToWorkorder := $request.returnToWorkOrder;
	/* boolean determining if inventory will be returned to original workorder */
	{
		"payload": {
			"create": $request
				.{
					"id": $id,
					"workOrderPriorityId": priority.id,
					"originalQuantity": quantity,
					"quantity": quantity,
					"active": true,
					"description": WONote & "\n\n"
						& "REWORK Generated from workorder number: "
						& $returnWO.number,
					"orderReference": returnToWorkOrder
						? $returnWO.id
						: undefined,
					"transactionAt": $now(),
					"promiseAt": dueAt,
					"customData": {
						"reworkInventories": [$components.Table1.selectedRows.id],
						"returnToProcess": returnProcessA.id,
						"returnToWorkorderProcessId": returnWOP.id,
						"returnToProductStrategyId": returnWOP.productStrategyId,
						"returnToProductStrategyProcessId": returnWOP.productStrategyProcessId
					},
					"workOrderStatusId": "Planned",
					"facilityId": $returnWO.facilityId,
					"workOrderTypeId": "Rework",
					"customerId": $returnWO.customerId,
					"productId": id
				}
		},
		"payloadInventory": [
			$components
				.Table1
				.selectedRows
				.{
					"update": { "inventoryStatusId": "ReworkPending" },
					"where": { "id": id }
				}
		],
		/* If not returning to original workorder quantity must be reduced on remaining operations to allow completion */
		"payloadWorkOrderUpdate": $returnToWorkorder
			? []
			: [
				$returnWO
					.(
						$reducedQuantity := quantity - $request.quantity;
						$processes := $state
							.context
							.LOCAL
							.returnWorkOrder
							.workOrderProcesses
							.edges
							.node^(<order)[$number(order) > $number($state.context.REQUEST.DATA.returnWOP.order)];
						{
							"workOrderUpdatePayload": {
								"update": { "quantity": $reducedQuantity },
								"where": { "id": id }
							},
							"workOrderProcessUpdatePayload": $processes
								.{
									"update": { "quantity": $reducedQuantity },
									"where": { "id": id }
								},
							"workOrderProcessDistributionUpdatePayload": $processes
								.workOrderProcessDistributions
								.edges
								.node
								.{
									"update": {
										"balanceQuantity": $reducedQuantity,
										"requiredQuantity": $reducedQuantity
									},
									"where": { "id": id }
								},
							"workOrderProcessDistributionGroupUpdatePayload": $processes
								.workOrderProcessDistributions
								.edges
								.node
								.distributionGroup
								.{
									"update": {
										"balanceQuantity": balanceQuantity
											- $request.quantity,
										"requiredQuantity": requiredQuantity
											- $request.quantity
									},
									"where": { "id": id }
								}
						}
					)
			]
	}
)

(
	$process := $components.SelProcTable.data;
	$newWorkorder := createWorkOrder;
	{
		"payload": $process#$i.(
				$order := $string(newSequence * 10 + 10);
				$id := $cuid();
				$processCount:= $count($process);
				{
					"create": {
						"id": $id,
						"productStrategyProcessId": undefined,
						"workOrderId": $newWorkorder.id,
						"quantity": $newWorkorder.quantity,
						"workOrderProcessStatusId": "New",
						"order": $order,
						"code": /*$order & "-" &*/ code,
						"productionTypeId": "Rework",
						"workcenterId": workcenter.id,
            "final": $processCount = $i + 1 ? true : false,
						"finishedGood": $processCount = $i + 1 ? true : false,
						"wip": $processCount = $i + 1 ? false : true,
						"processId": processId,
						"note":processNote,
						"description":description
					}
				}
			)
	}
)

data.query:
query Query($where: WorkOrderWhereInput, $orderBy: [WorkOrderOrderByInput!], $first: Int, $after: String) {
  workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        originalQuantity
        quantity
        active
        facilityId
        productId
        product {
          id
          code
        }
        workOrderProcesses {
          edges {
            node {
              id
              code
              workcenterId
            }
          }
        }
      }
    }
  }
}

